/**
 * Test flows for Daily trigger
 *
 * Flow 1: Tests daily scheduled trigger with time configuration
 * Flow 2: Tests DEF0777644 - Demonstrates that only mandatory fields are required
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Flow 1: Daily trigger with all parameters
export const testDailyTrigger = Flow(
    {
        $id: Now.ID['test_daily_trigger_flow'],
        name: 'Test Daily Trigger',
        description: 'Tests the Daily trigger running at specified time',
    },
    wfa.trigger(
        trigger.scheduled.daily,
        { $id: Now.ID['test_daily_trigger'] },
        {
            time: Time(
                {
                    hours: 8,
                    minutes: 30,
                    seconds: 0,
                },
                'UTC'
            ),
        }
    ),
    (_params) => {
        // Log trigger outputs
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['test_daily_trigger_log'],
            },
            {
                log_level: 'info',
                log_message: `Daily Trigger - Run Start Time: ${wfa.dataPill(_params.trigger.run_start_time, 'glide_date_time')}, Run Start Date/Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}`,
            }
        )
    }
)

// Flow 2: Daily trigger with mandatory fields only (DEF0777644)
export const testDailyTriggerMandatoryOnly = Flow(
    {
        $id: Now.ID['test_daily_trigger_mandatory_only_flow'],
        name: 'Test Daily Trigger - Mandatory Only',
        description: 'DEF0777644: Tests Daily trigger with only mandatory time input',
    },
    wfa.trigger(
        trigger.scheduled.daily,
        { $id: Now.ID['test_daily_trigger_mandatory_only'] },
        {
            time: Time(
                {
                    hours: 9,
                    minutes: 0,
                    seconds: 0,
                },
                'UTC'
            ),
        }
    ),
    (_params) => {
        // Log trigger execution
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_daily_trigger_mandatory_only_log'] },
            {
                log_level: 'info',
                log_message: `Daily Trigger (Mandatory Only) - Run Start Time: ${wfa.dataPill(_params.trigger.run_start_time, 'glide_date_time')}, Run Start Date/Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}`,
            }
        )
    }
)
